        "code": "def main(user_url: str):
	# Transform GitHub URL to API URL
	# Example: https://github.com/owner/repo -> https://api.github.com/repos/owner/repo/git/trees/main?recursive=1
	if 'github.com' in user_url:
		parts = user_url.replace('https://github.com/', '').replace('http://github.com/', '').strip('/')
		if '/' in parts:
			owner_repo = parts.split('/')[:2]
			api_url = f"https://api.github.com/repos/{owner_repo[0]}/{owner_repo[1]}/git/trees/main?recursive=1"
		else:
			api_url = user_url
	else:
		api_url = user_url
	return {
		"api_url": api_url
	}"
      }
    },
