      "param": {
        "variables": [["response", ["body", "3"]]],
        "outputs": [["file_structure", "string"]],
        "code": "def main(response: str):
	import json
	try:
		data = json.loads(response)
		if 'tree' not in data:
			return {"file_structure": "Error: Unable to parse repository structure. " + response[:200]}

		tree = data['tree']
		# Build tree structure
		tree_dict = {}
		for item in tree:
			path = item.get('path', '')
			item_type = item.get('type', '')
			tree_dict[path] = item_type

		# Sort paths for better display
		sorted_paths = sorted(tree_dict.keys())

		# Format as tree view
		lines = []
		for i, path in enumerate(sorted_paths):
			item_type = tree_dict[path]
			parts = path.split('/')
			depth = len(parts) - 1
			name = parts[-1]

			# Determine if this is the last item at this level
			is_last = i == len(sorted_paths) - 1
			if not is_last:
				next_path = sorted_paths[i + 1]
				next_parts = next_path.split('/')
